        entity.HasDiscriminator<string>("Discriminator");

        // Preserve EF Core 8 compound id format "Product|123" (EF Core 9 defaults to key-only).
        // Existing documents use the old format; FindAsync would fail without this.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // HasIndex removed — EF Core 9 Cosmos provider throws at startup.
    // Manage indexing via the container's indexing policy (Azure Portal / Bicep / Terraform).
}

